export type ParsedReviseMintedMetadataInstruction<
  TProgram extends string = typeof KATHA_REGISTRY_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    artwork: TAccountMetas[1];
    head: TAccountMetas[2];
    currentRevision: TAccountMetas[3];
    revision: TAccountMetas[4];
    collection: TAccountMetas[5];
    collectionAuthority: TAccountMetas[6];
    asset: TAccountMetas[7];
    registrationAuthority: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
    coreProgram: TAccountMetas[10];
  };
  data: ReviseMintedMetadataInstructionData;
};

export function parseReviseMintedMetadataInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedReviseMintedMetadataInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 11,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      artwork: getNextAccount(),
      head: getNextAccount(),
      currentRevision: getNextAccount(),
      revision: getNextAccount(),
      collection: getNextAccount(),
      collectionAuthority: getNextAccount(),
      asset: getNextAccount(),
      registrationAuthority: getNextAccount(),
      systemProgram: getNextAccount(),
      coreProgram: getNextAccount(),
    },
    data: getReviseMintedMetadataInstructionDataDecoder().decode(instruction.data),
  };
}
